import React from "react";
import { Avatar, Box, IconButton, Stack, Typography } from "@mui/material";
import { alpha, useTheme } from "@mui/material/styles";
import { Bell, CaretLeft, CaretRight, Image, Info, Key, Keyboard, Lock, Moon, PencilSimple, User } from "phosphor-react";
import Shortcuts from "../../sections/main/Settings/Shortcuts";
import ThemeDialog from "../../sections/main/Settings/ThemeDialog";
import { useSelector } from "react-redux";
import { useNavigate } from "react-router-dom";
import useResponsive from "../../hooks/useResponsive";
import BottomNav from "../../layouts/dashboard/BottomNav";

const Settings = () => {
  const theme = useTheme();
  const isDesktop = useResponsive("up", "md");
  const { user } = useSelector((state) => state.app);
  const [openShortcuts, setOpenShortcuts] = React.useState(false);
  const [openTheme, setOpenTheme] = React.useState(false);
  const navigate = useNavigate();

  const sections = [
    {
      title: "Preferences",
      items: [
        { icon: <Bell size={20} />, title: "Notifications", subtitle: "Messages, calls, and sounds" },
        { icon: <Moon size={20} />, title: "Appearance", subtitle: `${theme.palette.mode === "dark" ? "Dark" : "Light"} mode`, action: () => setOpenTheme(true) },
        { icon: <Image size={20} />, title: "Chat wallpaper", subtitle: "Personalize your conversations" },
        { icon: <Keyboard size={20} />, title: "Keyboard shortcuts", subtitle: "Move through ConnectO faster", action: () => setOpenShortcuts(true) },
      ],
    },
    {
      title: "Privacy and support",
      items: [
        { icon: <Lock size={20} />, title: "Privacy", subtitle: "Blocked contacts and visibility" },
        { icon: <Key size={20} />, title: "Security", subtitle: "Sessions and account protection" },
        { icon: <Info size={20} />, title: "Help and feedback", subtitle: "Support, shortcuts, and app info" },
      ],
    },
  ];

  return (
    <Box sx={{ width: "100%", height: "100vh", overflowY: "auto", bgcolor: "background.default", pb: isDesktop ? 5 : 12 }}>
      {!isDesktop && <BottomNav />}
      <Stack sx={{ width: "100%", maxWidth: 880, mx: "auto", px: { xs: 2, sm: 4 }, py: { xs: 2.5, sm: 4 } }} spacing={3}>
        <Stack direction="row" alignItems="center" spacing={1.5}>
          <IconButton aria-label="Back to chats" onClick={() => navigate("/app")}><CaretLeft size={21} /></IconButton>
          <Stack>
            <Typography variant="h4" sx={{ fontSize: 28 }}>Settings</Typography>
            <Typography variant="caption" color="text.secondary">Make ConnectO work for you</Typography>
          </Stack>
        </Stack>

        <Stack direction={{ xs: "column", sm: "row" }} alignItems={{ xs: "flex-start", sm: "center" }} spacing={2.5} sx={{ p: { xs: 2.5, sm: 3 }, borderRadius: "22px", bgcolor: "background.paper", border: `1px solid ${alpha(theme.palette.text.primary, 0.08)}`, boxShadow: theme.palette.mode === "light" ? "0 14px 42px rgba(31,42,68,.08)" : "0 14px 42px rgba(0,0,0,.2)" }}>
          <Box sx={{ position: "relative" }}>
            <Avatar src={user?.avatar} alt={user?.firstName} sx={{ width: 78, height: 78, bgcolor: alpha(theme.palette.primary.main, 0.12), color: "primary.main", fontSize: 26 }}>{user?.firstName?.charAt(0)}</Avatar>
            <IconButton aria-label="Edit profile" onClick={() => navigate("/profile")} size="small" sx={{ position: "absolute", right: -4, bottom: -4, width: 30, height: 30, color: "white", bgcolor: "primary.main", "&:hover": { bgcolor: "primary.dark" } }}><PencilSimple size={14} /></IconButton>
          </Box>
          <Stack flex={1} minWidth={0}>
            <Typography variant="h5" noWrap>{`${user?.firstName || ""} ${user?.lastName || ""}`.trim() || "Your profile"}</Typography>
            <Typography variant="body2" color="text.secondary" noWrap>{user?.email}</Typography>
            <Typography variant="caption" color="text.secondary" sx={{ mt: 0.5 }}>{user?.about || "Available on ConnectO"}</Typography>
          </Stack>
          <IconButton aria-label="Open profile" onClick={() => navigate("/profile")} sx={{ bgcolor: alpha(theme.palette.text.primary, 0.04) }}><User size={20} /></IconButton>
        </Stack>

        {sections.map((section) => (
          <Stack key={section.title} spacing={1.25}>
            <Typography variant="overline" color="text.secondary" sx={{ pl: 1, letterSpacing: ".1em" }}>{section.title}</Typography>
            <Stack sx={{ borderRadius: "22px", overflow: "hidden", bgcolor: "background.paper", border: `1px solid ${alpha(theme.palette.text.primary, 0.08)}` }}>
              {section.items.map((item, index) => (
                <Stack
                  key={item.title}
                  component="button"
                  type="button"
                  direction="row"
                  alignItems="center"
                  spacing={1.75}
                  onClick={item.action}
                  sx={{ width: "100%", minHeight: 72, px: 2.25, border: 0, borderBottom: index < section.items.length - 1 ? `1px solid ${alpha(theme.palette.text.primary, 0.07)}` : 0, bgcolor: "transparent", color: "text.primary", textAlign: "left", cursor: item.action ? "pointer" : "default", font: "inherit", transition: "background-color 150ms ease", "&:hover": { bgcolor: item.action ? alpha(theme.palette.primary.main, 0.055) : "transparent" } }}
                >
                  <Box sx={{ width: 40, height: 40, flexShrink: 0, borderRadius: "13px", display: "grid", placeItems: "center", color: "primary.main", bgcolor: alpha(theme.palette.primary.main, 0.09) }}>{item.icon}</Box>
                  <Stack flex={1} minWidth={0}><Typography variant="subtitle2">{item.title}</Typography><Typography variant="caption" color="text.secondary" noWrap>{item.subtitle}</Typography></Stack>
                  {item.action && <CaretRight size={17} color={theme.palette.text.secondary} />}
                </Stack>
              ))}
            </Stack>
          </Stack>
        ))}
      </Stack>
      {openTheme && <ThemeDialog open handleClose={() => setOpenTheme(false)} />}
      {openShortcuts && <Shortcuts open handleClose={() => setOpenShortcuts(false)} />}
    </Box>
  );
};

export default Settings;
